using UnityEngine.UI;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using Newtonsoft.Json.Linq;
using XCharts.Runtime;

public static class GeneratedCode
{
    public static void Execute()
    {
        // 1. Load Data
        string dataPath = Path.Combine(Application.streamingAssetsPath, "DxRData/education/student_scores.json");
        if (!File.Exists(dataPath))
        {
            Debug.LogError("Data file not found at: " + dataPath);
            return;
        }

        string jsonData = File.ReadAllText(dataPath);
        JArray dataArray = JArray.Parse(jsonData);

        // 2. User Status and Layout Parameters
        // User is at (0, 1.7, 0) looking towards -Z
        Vector3 userPos = new Vector3(0.00f, 1.70f, 0.00f);
        Vector3 userForward = new Vector3(0.00f, 0.00f, -1.00f);
        Vector3 userRight = new Vector3(-1.00f, 0.00f, 0.00f);

        float spacing = 1.20f; // Distance between individual charts
        float distanceInFront = 2.50f; // Distance from user
        float chartHeight = 1.50f; // Height from the floor
        int studentCount = dataArray.Count;

        // 3. Generate a chart for each student
        for (int i = 0; i < studentCount; i++)
        {
            JToken student = dataArray[i];
            string studentId = student["student_id"].ToString();
            string studentName = student["name"].ToString();
            float math = student["math_score"].Value<float>();
            float science = student["science_score"].Value<float>();
            float english = student["english_score"].Value<float>();

            // Create unique view_id
            string viewId = "StudentScores_" + studentId;
            GameObject chartObj = new GameObject(viewId);

            // Setup World Space Canvas
            Canvas canvas = chartObj.AddComponent<Canvas>();
            canvas.renderMode = RenderMode.WorldSpace;
            chartObj.AddComponent<CanvasScaler>();
            chartObj.AddComponent<GraphicRaycaster>();

            RectTransform rectTransform = chartObj.GetComponent<RectTransform>();
            rectTransform.sizeDelta = new Vector2(500f, 400f);
            // Scale down to fit in world space (approx 1m wide)
            chartObj.transform.localScale = new Vector3(0.002f, 0.002f, 0.002f);

            // Add Bar Chart component
            BarChart chart = chartObj.AddComponent<BarChart>();
            chart.Init();

            // Configure Title
            var title = chart.GetOrAddChartComponent<Title>();
            title.text = studentName;
            title.subText = "ID: " + studentId;

            // Configure Legend
            var legend = chart.GetOrAddChartComponent<Legend>();
            legend.show = true;

            // Configure X-Axis (Categories)
            var xAxis = chart.GetOrAddChartComponent<XAxis>();
            xAxis.type = Axis.AxisType.Category;
            chart.AddXAxisData("Math");
            chart.AddXAxisData("Science");
            chart.AddXAxisData("English");

            // Configure Y-Axis (Values 0-100)
            var yAxis = chart.GetOrAddChartComponent<YAxis>();
            yAxis.type = Axis.AxisType.Value;
            yAxis.minMaxType = Axis.AxisMinMaxType.Custom;
            yAxis.min = 0.00f;
            yAxis.max = 100.00f;

            // Add Data Series
            var serie = chart.AddSerie<Bar>("Scores");
            serie.itemStyle.color = "#5470C6FF"; // Professional blue

            chart.AddData(0, math);
            chart.AddData(0, science);
            chart.AddData(0, english);

            // 4. Calculate Spatial Placement
            // Calculate horizontal offset to center the row of charts in front of the user
            float horizontalOffset = (i - (studentCount - 1) / 2.0f) * spacing;
            Vector3 targetPosition = userPos + (userForward * distanceInFront) + (userRight * horizontalOffset);
            targetPosition.y = chartHeight;

            chartObj.transform.position = targetPosition;

            // Rotate chart to face the user (UI forward is the back of the canvas)
            chartObj.transform.rotation = Quaternion.LookRotation(-userForward);
        }
    }
}

